patch as (select a, (select jsonb_object_agg(v->>'code', v) from jsonb_array_elements(a) v) p from src)
update public.catalog_config c
   set value = (
         select coalesce(jsonb_agg(e || coalesce((select p from patch) -> (e->>'code'), '{}'::jsonb) order by ord), '[]'::jsonb)
           from jsonb_array_elements(c.value) with ordinality as t(e, ord)
       ) || coalesce((
         -- новые — в порядке документа (первая ткань категории — по умолчанию)
         select jsonb_agg(n.v order by n.ord)
           from jsonb_array_elements((select a from patch)) with ordinality as n(v, ord)
          where not exists (select 1 from jsonb_array_elements(c.value) x where x->>'code' = n.v->>'code')
       ), '[]'::jsonb),
       updated_at = now()
 where c.key = 'fabricsCatalog';

