Usage":0.2,"hasHood":true},"ZH-004":{"mainFabricUsage":1.4,"trimCode":"kashkorse","trimUsage":0.2,"hasHood":true},"ZH-005":{"mainFabricUsage":1.4,"trimCode":"kashkorse","trimUsage":0.2,"hasHood":true},"ZH-006":{"mainFabricUsage":1.4,"trimCode":"kashkorse","trimUsage":0.2,"hasHood":true},"PL-001":{"mainFabricUsage":0.8,"trimCode":"collar-cotton","trimUsage":1,"extraMaterials":37.08},"PL-002":{"mainFabricUsage":0.9,"trimCode":"collar-cotton","trimUsage":1,"extraMaterials":37.08},"RG-001":{"mainFabricUsage":1,"trimCode":"collar-cotton","trimUsage":1,"extraMaterials":37.08},"RG-002":{"mainFabricUsage":1.3,"trimCode":"collar-cotton","trimUsage":1,"extraMaterials":37.08},"OL-001":{"mainFabricUsage":1.2,"trimCode":"kashkorse","trimUsage":0.2,"sewingPrice":285.9,"markupGroup":"A"},"BM-001":{"mainFabricUsage":1.3,"trimCode":"kashkorse","trimUsage":0.3,"sewingPrice":550},"BM-002":{"mainFabricUsage":1.2,"trimCode":"kashkorse","trimUsage":0.3,"sewingPrice":550},"P-001":{"mainFabricUsage":1.2,"trimCode":null,"trimUsage":0,"zones":["front","back","leg-l","leg-r"]},"P-002":{"mainFabricUsage":1.3,"trimCode":null,"trimUsage":0,"zones":["front","back","leg-l","leg-r"]},"P-003":{"mainFabricUsage":1.2,"trimCode":null,"trimUsage":0,"zones":["front","back","leg-l","leg-r"]},"P-004":{"mainFabricUsage":1.3,"trimCode":null,"trimUsage":0,"zones":["front","back","leg-l","leg-r"]},"P-005":{"mainFabricUsage":1.3,"trimCode":null,"trimUsage":0,"zones":["front","back","leg-l","leg-r"]},"P-006":{"mainFabricUsage":1.3,"trimCode":null,"trimUsage":0,"zones":["front","back","leg-l","leg-r"]},"SH-001":{"mainFabricUsage":1,"trimCode":null,"trimUsage":0,"zones":["front","back","leg-l","leg-r"]},"SH-002":{"mainFabricUsage":0.9,"trimCode":null,"trimUsage":0,"zones":["front","back","leg-l","leg-r"]},"BAG-001":{"mainFabricUsage":0.5,"trimCode":null,"trimUsage":0,"zones":["side-a","side-b"]},"BAG-002":{"mainFabricUsage":0.9,"trimCode":null,"trimUsage":0,"zones":["side-a","side-b"]},"BAG-003":{"mainFabricUsage":0.8,"trimCode":null,"trimUsage":0,"zones":["side-a","side-b"]},"BAG-004":{"mainFabricUsage":0.7,"trimCode":null,"trimUsage":0,"zones":["side-a","side-b"]}}'::jsonb p)
update public.app_config c
   set value = (
         select coalesce(jsonb_agg(
                  (e || coalesce((select p from patch) -> (e->>'code'), '{}'::jsonb))
                  || jsonb_build_object('description',
                       regexp_replace(coalesce(e->>'description', ''), ',?\s*(\d+\s*%\s*)?хлопок\s*\d+\s*г/м²', '', 'gi'))
                  || case when coalesce(e->>'description', '') ilike '%карман%'
                          then '{"hasPocket": true}'::jsonb else '{}'::jsonb end
                  order by ord), '[]'::jsonb)
           from jsonb_array_elements(c.value) with ordinality as t(e, ord)
          where e->>'code' not in ('futbolka', 'hudi')
       ),
       updated_at = now()
 where c.key = 'sku_catalog';

